//! A check that must give zero: the config generated by the app, with the same inputs as the `-Web` branch of
//! mango-code.ps1, is identical to the one PowerShell generated (`fixtures/opencode.ps-web.json`) except for the
//! intended differences listed in `expected_from_ps`.

use agent_cfg::tools::{instructions, Detection};
use agent_cfg::team::{self, Choices};
use agent_cfg::{plan, AgentInputs, BrowserInputs, AgentModel};
use mango_common::{tr, Paths};
use serde_json::{json, Value};
use std::path::{Path, PathBuf};

/// Root of the distribution the fixture was generated with.
const FIXTURE_DIST: &str = r"C:\Test\dist";

/// The real distribution: the repo's `launcher/`, next to `app/`.
fn dist() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).ancestors().nth(3).unwrap().join("launcher")
}

/// A unique temporary folder per test, with a fake opencode build inside.
struct Sandbox {
    root: PathBuf,
}

impl Sandbox {
    fn new(name: &str) -> Sandbox {
        let root = std::env::temp_dir().join(format!("agent-cfg-{}-{name}", std::process::id()));
        let _ = std::fs::remove_dir_all(&root);
        std::fs::create_dir_all(root.join("opencode").join("web")).unwrap();
        std::fs::write(root.join("opencode").join("web").join("mango-code.exe"), b"").unwrap();
        Sandbox { root }
    }

    fn paths(&self, dist: PathBuf) -> Paths {
        Paths {
            dist,
            engines: self.root.join("engine"),
            models: self.root.join("models"),
            opencode: self.root.join("opencode"),
            data: self.root.join("data"),
        }
    }

    fn exe(&self) -> String {
        self.root.join("opencode").join("web").join("mango-code.exe").to_string_lossy().into_owned()
    }
}

impl Drop for Sandbox {
    fn drop(&mut self) {
        let _ = std::fs::remove_dir_all(&self.root);
    }
}

/// The inputs of the run the fixture comes from: toq model, TOQ-v1, ctx 122880, without images.
fn inputs() -> AgentInputs {
    AgentInputs {
        engine_url: "http://127.0.0.1:8080".into(),
        models: vec![AgentModel { key: "toq".into(), label: "TOQ-v1".into(), ctx: 122880, images: false }],
        default_model: "toq".into(),
        port: 4196,
        voice_url: None,
        tools: pc(),
        browser: BrowserInputs { preview_port: 51789, choice: PathBuf::from(r"C:\data\browser.json") },
        team: None,
    }
}

/// A PC with Python and Git but without Node, Java, etc.: the generated text depends on this.
fn pc() -> Detection {
    Detection { python: Some("3.12.4".into()), git: Some("2.47.1".into()), ..Default::default() }
}

fn read_json(p: &Path) -> Value {
    let t = std::fs::read_to_string(p).unwrap();
    serde_json::from_str(t.trim_start_matches('\u{feff}')).unwrap()
}

fn replace_in_strings(v: &mut Value, from: &str, to: &str) {
    match v {
        Value::String(s) => *s = s.replace(from, to),
        Value::Array(a) => a.iter_mut().for_each(|x| replace_in_strings(x, from, to)),
        Value::Object(m) => m.values_mut().for_each(|x| replace_in_strings(x, from, to)),
        _ => {}
    }
}

fn drop_annotations(v: &mut Value) {
    match v {
        Value::Object(m) => {
            m.retain(|k, _| !k.starts_with('_'));
            m.values_mut().for_each(drop_annotations);
        }
        Value::Array(a) => a.iter_mut().for_each(drop_annotations),
        _ => {}
    }
}

/// PowerShell's config brought to what the app must generate. EVERY intended difference is here.
fn expected_from_ps(dist: &Path, data: &Path, exe: &str) -> Value {
    let mut v = read_json(&Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/opencode.ps-web.json"));

    // 1. Paths: the app's distribution is elsewhere compared to the development repo.
    replace_in_strings(&mut v, FIXTURE_DIST, &dist.to_string_lossy());

    let root = v.as_object_mut().unwrap();
    // 2. The `openrouter` cloud provider (fake key, "unused" model) isn't needed by the app.
    assert!(root["provider"].as_object_mut().unwrap().remove("openrouter").is_some());
    // 4. The MCPs don't start with `node` (absent on the user's PC) but with mango-code.exe in runtime mode
    //    (BUN_BE_BUN=1), with cwd = the distribution and MANGO_RUNTIME = a writable app folder for profile and logs
    //    (the program folder may not be writable);
    //    No guest Chrome (our own profile, separate windows): the agent's browser is the app's Preview panel.
    //    Which panel, and whether to use the user's Chrome instead, are told by two environment variables of the
    //    process (random port at every start), NOT by the config: see `process_port_environment_and_health`.
    //    The `documents` server (Word, Excel, PowerPoint, PDF) is in the template since after the fixture was
    //    generated: it is added here before the transformation, so it undergoes it like the others.
    root["mcp"].as_object_mut().unwrap().insert(
        "documents".into(),
        json!({
            "type": "local",
            "command": ["node", format!("{}\\mango-documents\\mcp.mjs", dist.display())],
            "enabled": true,
            "timeout": 120000
        }),
    );
    for (_, srv) in root["mcp"].as_object_mut().unwrap().iter_mut() {
        let cmd = srv["command"].as_array_mut().unwrap();
        assert_eq!(cmd[0], json!("node"));
        cmd[0] = json!(exe);
        srv["environment"] =
            json!({"BUN_BE_BUN": "1", "MANGO_RUNTIME": data.join("mcp").to_string_lossy()});
        srv["cwd"] = json!(dist.to_string_lossy());
    }
    // 5. The screenshot tool is always on (the fixture, from a model without images, had it off): the user sees the
    //    screenshot in the chat, the model only gets a text note.
    root["tools"]["chrome-devtools_take_screenshot"] = json!(true);
    // 5b. The «@» agents explore and general go through the `task` tool, which is off: in the «@» menu they would
    //     be entries that don't work, so they are disabled.
    root.insert("agent".into(), json!({"explore": {"disable": true}, "general": {"disable": true}}));
    // 5d. One model for each local model, with the mango-models.json key as id (the engine manager reads it in the
    //     request): in the fixture there was a single `local`.
    let models = root["provider"]["mango"]["models"].as_object_mut().unwrap();
    let local = models.remove("local").unwrap();
    models.insert("toq".into(), local);
    root["model"] = json!("mango/toq");
    root["small_model"] = json!("mango/toq");
    // 5e. The web instructions are added by the mango-discipline plugin according to the request's model.
    let ins = root["instructions"].as_array_mut().unwrap();
    assert!(ins.remove(1).as_str().unwrap().ends_with("MANGO-web-text.md"));
    // 5c. At the end of `instructions` there is the «Tools on this PC» section, generated at every start from the
    //     detection of Python, Node, Git, etc. (`tools.rs`): on the user's PC there may be nothing to program with,
    //     and without the list the model would write scripts it can't run. The file is in the generated config's
    //     folder, not in the distribution.
    root["instructions"]
        .as_array_mut()
        .unwrap()
        .push(json!(data.join("opencode-home").join("MANGO-pc.md").to_string_lossy()));
    // 6. The template's `_*` notes (for whoever reads the template) don't end up in the user's config: they cite
    //    PowerShell and people's names, and some would be false.
    drop_annotations(&mut v);
    v
}

#[test]
fn config_identical_to_powershell_except_for_the_intended_differences() {
    let sb = Sandbox::new("zero");
    let paths = sb.paths(dist());
    let p = plan(&paths, &inputs()).unwrap();
    let got = read_json(&p.config_dir.join("opencode.json"));
    assert_eq!(got, expected_from_ps(&paths.dist, &paths.data, &sb.exe()));
}

#[test]
fn the_comparison_sees_the_differences_of_the_model_with_images() {
    // A check that must GIVE a difference: if the test above compared too little, it would pass even changing the
    // model.
    let sb = Sandbox::new("images");
    let paths = sb.paths(dist());
    let mut inp = inputs();
    inp.models[0].images = true;
    let p = plan(&paths, &inp).unwrap();
    let got = read_json(&p.config_dir.join("opencode.json"));
    assert_ne!(got, expected_from_ps(&paths.dist, &paths.data, &sb.exe()));
    let m = &got["provider"]["mango"]["models"]["toq"];
    assert_eq!(m["attachment"], json!(true));
    assert_eq!(m["modalities"]["input"], json!(["text", "image"]));
    assert_eq!(got["tools"]["chrome-devtools_take_screenshot"], json!(true));
}

#[test]
fn one_model_for_each_local_model() {
    let sb = Sandbox::new("models");
    let paths = sb.paths(dist());
    let mut inp = inputs();
    inp.models.push(AgentModel { key: "3.8".into(), label: "Qwen3.8-27B".into(), ctx: 81920, images: true });
    inp.models.push(AgentModel { key: "lfm".into(), label: "LFM2.5".into(), ctx: 131072, images: false });
    inp.default_model = "3.8".into();
    let p = plan(&paths, &inp).unwrap();
    let got = read_json(&p.config_dir.join("opencode.json"));
    let m = got["provider"]["mango"]["models"].as_object().unwrap();
    // The order in which the app lists them (the catalog's), not the alphabetical one: the web UI shows it that way.
    assert_eq!(m.keys().collect::<Vec<_>>(), ["toq", "3.8", "lfm"]);
    assert_eq!(m["3.8"]["limit"], json!({"context": 81920, "output": 10240}));
    assert_eq!(m["lfm"]["limit"], json!({"context": 131072, "output": 16384}));
    assert_eq!(m["3.8"]["modalities"]["input"], json!(["text", "image"]));
    assert_eq!(m["lfm"]["attachment"], json!(false));
    assert_eq!(m["3.8"]["name"], json!("Qwen3.8-27B"));
    assert_eq!(got["model"], json!("mango/3.8"));
    assert_eq!(got["small_model"], json!("mango/3.8"));
    let env = |k: &str| p.spec.env.iter().find(|(n, _)| n == k).map(|(_, v)| v.clone());
    assert_eq!(env("MANGO_IMAGE_MODELS").as_deref(), Some("3.8"));

    inp.default_model = "xyz".into();
    let e = plan(&paths, &inp).unwrap_err();
    assert!(format!("{e:#}").contains("xyz"), "{e:#}");
}

#[test]
fn process_port_environment_and_health() {
    let sb = Sandbox::new("spec");
    let paths = sb.paths(dist());
    let mut inp = inputs();
    inp.voice_url = Some("http://127.0.0.1:4097".into());
    let p = plan(&paths, &inp).unwrap();
    let s = &p.spec;
    assert_eq!(s.name, "agent");
    assert_eq!(s.exe.to_string_lossy(), sb.exe());
    assert_eq!(s.args, ["serve", "--hostname", "127.0.0.1", "--port", "4196"]);
    assert_eq!(p.url, "http://127.0.0.1:4196");
    assert_eq!(s.health_url.as_deref(), Some("http://127.0.0.1:4196/global/health"));
    assert_eq!(s.ready_timeout_s, 60);
    assert_eq!(s.cwd.as_deref(), Some(Path::new(&std::env::var_os("USERPROFILE").unwrap())));
    assert_eq!(p.config_dir, paths.data.join("opencode-home"));

    let env = |k: &str| s.env.iter().find(|(n, _)| n == k).map(|(_, v)| v.as_str());
    assert_eq!(env("OPENCODE_CONFIG_DIR"), Some(&*p.config_dir.to_string_lossy()));
    assert_eq!(env("MANGO_HOME"), Some(&*paths.dist.to_string_lossy()));
    assert_eq!(env("MANGO_ENGINE_URL"), Some("http://127.0.0.1:8080"));
    assert_eq!(env("MANGO_IMAGE_MODELS"), Some(""));
    // The prompt settings for all folders live in the app's data (with MANGO_DATA, in the test's).
    assert_eq!(env("MANGO_SETTINGS"), Some(&*paths.data.join("settings.json").to_string_lossy()));
    assert_eq!(env("MANGO_SYSTEM_LANGUAGE"), Some(mango_common::i18n::system_lang().code()));
    assert_eq!(env("MANGO_VOICE_URL"), Some("http://127.0.0.1:4097"));
    // The agent's browser: the app's panel, by port; the «Use my Chrome» choice by file. The port lives in the
    // process environment and not in the config written to disk; the old MANGO_CHROME=own (guest Chrome) no longer exists.
    assert_eq!(env("MANGO_PANEL_CDP"), Some("51789"));
    assert_eq!(env("MANGO_BROWSER_CHOICE"), Some(r"C:\data\browser.json"));
    assert_eq!(env("MANGO_CHROME"), None);
    let config = std::fs::read_to_string(p.config_dir.join("opencode.json")).unwrap();
    assert!(!config.contains("51789") && !config.contains("MANGO_CHROME"), "the port or the guest Chrome ended up in the config");
    for k in [
        "OPENCODE_DISABLE_AUTOUPDATE",
        "OPENCODE_DISABLE_MODELS_FETCH",
        "OPENCODE_DISABLE_SHARE",
        "OPENCODE_DISABLE_LSP_DOWNLOAD",
        // isolation from what is on the PC (Claude Code, external skills)
        "OPENCODE_DISABLE_CLAUDE_CODE",
        "OPENCODE_DISABLE_EXTERNAL_SKILLS",
        "OPENCODE_DISABLE_BUILTIN_COMMANDS",
    ] {
        assert_eq!(env(k), Some("1"), "{k}");
    }
    // conversations, config, cache and logs only in the app's data
    for k in ["XDG_DATA_HOME", "XDG_CONFIG_HOME", "XDG_CACHE_HOME", "XDG_STATE_HOME"] {
        assert!(env(k).is_some_and(|v| v.starts_with(&*paths.data.to_string_lossy())), "{k}");
    }
    let content: Value = serde_json::from_str(env("OPENCODE_CONFIG_CONTENT").unwrap()).unwrap();
    assert_eq!(content, json!({"enabled_providers": ["mango"], "permission": {"doom_loop": "allow"}}));
    assert_eq!(s.env_remove, ["OPENCODE_SERVER_PASSWORD", "OPENCODE_SERVER_USERNAME", "SHELL"]);
    // `bun` for the agent: the shim is at the head of the PATH and points to our executable
    assert_eq!(env("MANGO_BUN_EXE"), Some(&*sb.exe()));
    let bin = paths.data.join("bin");
    assert!(env("PATH").unwrap().starts_with(&format!("{};", bin.display())));
    assert!(bin.join("bun.cmd").is_file());

    // Without dictation the variable isn't set and the inherited one is removed.
    let p2 = plan(&paths, &inputs()).unwrap();
    assert!(p2.spec.env.iter().all(|(k, _)| k != "MANGO_VOICE_URL"));
    assert!(p2.spec.env_remove.contains(&"MANGO_VOICE_URL".to_string()));
}

#[test]
fn plugins_copied_and_old_ones_removed() {
    let sb = Sandbox::new("plugin");
    let paths = sb.paths(dist());
    let stale = paths.data.join("opencode-home").join("plugin").join("old.js");
    std::fs::create_dir_all(stale.parent().unwrap()).unwrap();
    std::fs::write(&stale, "x").unwrap();
    let p = plan(&paths, &inputs()).unwrap();
    let mut names: Vec<String> = std::fs::read_dir(p.config_dir.join("plugin"))
        .unwrap()
        .map(|e| e.unwrap().file_name().to_string_lossy().into_owned())
        .collect();
    names.sort();
    assert_eq!(names, ["mango-discipline.js", "mango-documents.js", "mango-project.js", "mango-web-diet.js"]);
    // the npm install is declared already done
    assert!(p.config_dir.join("node_modules").is_dir());
    assert!(p.config_dir.join("package-lock.json").is_file());
}

#[test]
fn clear_errors_instead_of_fallbacks() {
    let sb = Sandbox::new("errors");
    // distribution without a template
    let empty = sb.root.join("empty-dist");
    std::fs::create_dir_all(&empty).unwrap();
    let e = plan(&sb.paths(empty), &inputs()).unwrap_err();
    assert!(format!("{e:#}").contains("opencode.template.json"), "{e:#}");
    // opencode build missing
    let mut paths = sb.paths(dist());
    paths.opencode = sb.root.join("does-not-exist");
    let e = plan(&paths, &inputs()).unwrap_err();
    assert!(format!("{e:#}").contains("mango-code.exe"), "{e:#}");
}

#[test]
fn pc_tools_section_in_the_instructions() {
    let sb = Sandbox::new("tools");
    let paths = sb.paths(dist());
    let p = plan(&paths, &inputs()).unwrap();
    let got = read_json(&p.config_dir.join("opencode.json"));
    let ins = got["instructions"].as_array().unwrap();
    assert_eq!(ins.len(), 2);
    let file = PathBuf::from(ins[1].as_str().unwrap());
    assert_eq!(file, p.config_dir.join("MANGO-pc.md"));
    let text = std::fs::read_to_string(&file).unwrap();
    assert_eq!(text, instructions(&pc()));
    assert!(text.contains("Python 3.12; Git 2.47."), "{text}");
    assert!(text.contains("Not installed: Node, .NET, Java, Rust, Go."), "{text}");

    // A different PC gives a different text, and the file is updated at the next launch.
    let mut inp = inputs();
    inp.tools.node = Some("24.1.0".into());
    plan(&paths, &inp).unwrap();
    let new = std::fs::read_to_string(&file).unwrap();
    assert!(new.contains("Python 3.12; Node 24; Git 2.47."), "{new}");
}

// ---------------------------------------------------------------------------------------------- Team

const TEST_KEY: &str = "sk-or-v1-test-key-0123456789";

/// The Team as the app generates it with the `choices`, on the real catalog.
fn with_team(paths: &Paths, choices: &Choices) -> AgentInputs {
    let catalog = mango_common::catalog::read(paths).unwrap().root;
    AgentInputs {
        team: Some(team::TeamInputs {
            agents: choices.agents,
            manager: team::cloud_model(&catalog, &choices.manager).unwrap(),
            agent: team::cloud_model(&catalog, &choices.agent).unwrap(),
            key: TEST_KEY.into(),
        }),
        ..inputs()
    }
}

fn env_of<'a>(p: &'a agent_cfg::AgentPlan, k: &str) -> Option<&'a str> {
    p.spec.env.iter().find(|(n, _)| n == k).map(|(_, v)| v.as_str())
}

#[test]
fn team_off_leaves_nothing_in_the_config() {
    let sb = Sandbox::new("team-off");
    let paths = sb.paths(dist());
    let p = plan(&paths, &inputs()).unwrap();
    let got = read_json(&p.config_dir.join("opencode.json"));
    assert!(got["provider"].get("openrouter").is_none());
    assert!(got["agent"].get("team").is_none() && got["agent"].get("build").is_none());
    assert_eq!(got["plugin"], json!([]));
    assert_eq!(env_of(&p, "MANGO_TEAM_ROLE"), None);
    assert_eq!(env_of(&p, team::KEY_VAR), None);
    assert!(!paths.data.join("team").exists(), "without Team nothing is created");
    let content: Value = serde_json::from_str(env_of(&p, "OPENCODE_CONFIG_CONTENT").unwrap()).unwrap();
    assert_eq!(content["enabled_providers"], json!(["mango"]));
}

#[test]
fn team_on_manager_and_cloud_models() {
    let sb = Sandbox::new("team-on");
    let paths = sb.paths(dist());
    let p = plan(&paths, &with_team(&paths, &Choices::default())).unwrap();
    let got = read_json(&p.config_dir.join("opencode.json"));
    let id = "deepseek/deepseek-v4.1-flash-20260910";

    // the manager is an opencode agent with its own model; the normal conversation doesn't have its tools
    assert_eq!(got["agent"]["team"]["model"], json!(format!("openrouter/{id}")));
    assert_eq!(got["agent"]["team"]["mode"], json!("primary"));
    assert!(got["agent"]["team"].get("permission").is_none(), "the manager must see its tools");
    for tool in team::MANAGER_TOOLS {
        assert_eq!(got["agent"]["build"]["permission"][tool], json!("deny"), "{tool}");
    }
    // the local model stays the default, the cloud one is offered next to it
    assert_eq!(got["model"], json!("mango/toq"));
    let or = &got["provider"]["openrouter"];
    assert_eq!(or["options"]["baseURL"], json!("https://openrouter.ai/api/v1"));
    assert_eq!(or["options"]["apiKey"], json!("{env:MANGO_OPENROUTER_KEY}"));
    assert_eq!(or["models"].as_object().unwrap().keys().collect::<Vec<_>>(), [id], "manager and agent are the same model");
    assert_eq!(or["models"][id]["modalities"]["input"], json!(["text", "image"]));
    assert_eq!(or["models"][id]["limit"]["context"], json!(1048576));
    assert_eq!(or["models"][id]["cost"]["input"], json!(0.15));
    // the Team plugin is the terminal's, from the distribution (where it has node_modules next to it)
    let plugin = got["plugin"].as_array().unwrap();
    assert_eq!(plugin.len(), 1);
    assert_eq!(Path::new(plugin[0].as_str().unwrap()), paths.dist.join("opencode-home/plugin/mango-team.js"));

    let content: Value = serde_json::from_str(env_of(&p, "OPENCODE_CONFIG_CONTENT").unwrap()).unwrap();
    assert_eq!(content["enabled_providers"], json!(["mango", "openrouter"]));
    assert_eq!(env_of(&p, "MANGO_TEAM_ROLE"), Some("manager"));
    assert_eq!(env_of(&p, "MANGO_TEAM_AGENT"), Some("team"));
    assert_eq!(env_of(&p, "MANGO_AGENT_MAX"), Some("4"));
    assert_eq!(env_of(&p, "MANGO_AGENT_PORTS"), Some("4092,4093,4094,4095"));
    assert_eq!(env_of(&p, "MANGO_IMAGE_MODELS"), Some(id), "the manager sees images");
    assert_eq!(env_of(&p, team::KEY_VAR), Some(TEST_KEY));
}

#[test]
fn team_dev_and_agents_have_their_own_config() {
    let sb = Sandbox::new("team-roles");
    let paths = sb.paths(dist());
    let choices = Choices { agent: "qwen".into(), ..Choices::default() };
    plan(&paths, &with_team(&paths, &choices)).unwrap();
    let folder = team::folder(&paths);

    // the dev: the local model, its role, the plugin; no «team» agent
    let dev = read_json(&folder.join("dev-home/opencode.json"));
    assert_eq!(dev["model"], json!("mango/toq"));
    let instructions: Vec<&str> = dev["instructions"].as_array().unwrap().iter().filter_map(Value::as_str).collect();
    assert!(instructions.iter().any(|i| i.ends_with("MANGO-dev.md")), "{instructions:?}");
    assert!(dev["agent"].get("team").is_none());
    assert_eq!(dev["plugin"].as_array().unwrap().len(), 1);
    assert!(folder.join("dev-home/plugin/mango-discipline.js").is_file());

    // the agents: the agents' cloud model (here different from the manager's), their role
    let agent = read_json(&folder.join("agent-home/opencode.json"));
    assert_eq!(agent["model"], json!("openrouter/qwen/qwen3.8-27b"));
    assert_eq!(agent["small_model"], json!("openrouter/qwen/qwen3.8-27b"));
    let instructions: Vec<&str> = agent["instructions"].as_array().unwrap().iter().filter_map(Value::as_str).collect();
    assert!(instructions.iter().any(|i| i.ends_with("MANGO-agent.md")), "{instructions:?}");
    assert_eq!(agent["provider"]["openrouter"]["models"].as_object().unwrap().len(), 2, "manager and agents, two different models");

    // the app's server has the manager's model for the team agent
    let app = read_json(&paths.data.join("opencode-home/opencode.json"));
    assert_eq!(app["agent"]["team"]["model"], json!("openrouter/deepseek/deepseek-v4.1-flash-20260910"));
}

#[test]
fn team_number_of_agents() {
    for n in 0..=4u8 {
        let sb = Sandbox::new(&format!("team-agents-{n}"));
        let paths = sb.paths(dist());
        let p = plan(&paths, &with_team(&paths, &Choices { agents: n, ..Choices::default() })).unwrap();
        assert_eq!(env_of(&p, "MANGO_AGENT_MAX"), Some(&*n.to_string()));
        let launch = read_json(&team::folder(&paths).join("launch.json"));
        let agents = launch["agents"].as_array().unwrap();
        assert_eq!(agents.len(), n as usize);
        for (i, a) in agents.iter().enumerate() {
            assert_eq!(a["id"], json!(i + 1));
            assert_eq!(a["port"], json!(team::AGENT_PORTS[i]));
        }
        assert_eq!(launch["dev"]["port"], json!(team::DEV_PORT));
        assert_eq!(launch["exe"], json!(sb.exe()));
    }
}

#[test]
fn team_the_key_never_ends_up_on_disk() {
    let sb = Sandbox::new("team-key");
    let paths = sb.paths(dist());
    let p = plan(&paths, &with_team(&paths, &Choices::default())).unwrap();
    assert_eq!(env_of(&p, team::KEY_VAR), Some(TEST_KEY), "it reaches the process in the environment");

    fn files_with_the_key(dir: &Path, found: &mut Vec<PathBuf>) {
        for entry in std::fs::read_dir(dir).unwrap().flatten() {
            let f = entry.path();
            if f.is_dir() {
                files_with_the_key(&f, found);
            } else if std::fs::read(&f).unwrap().windows(TEST_KEY.len()).any(|w| w == TEST_KEY.as_bytes()) {
                found.push(f);
            }
        }
    }
    let mut found = Vec::new();
    files_with_the_key(&sb.root, &mut found);
    assert!(found.is_empty(), "the key is written in {found:?}");
    // and the spec describing the process doesn't put it in the arguments
    assert!(p.spec.args.iter().all(|a| !a.contains(TEST_KEY)));
}

#[test]
fn team_without_a_key_does_not_start() {
    let sb = Sandbox::new("team-no-key");
    let paths = sb.paths(dist());
    for key in [None, Some(String::new()), Some("  ".to_string())] {
        assert!(team::team_inputs(&paths, key).unwrap().is_none());
    }
    assert!(team::team_inputs(&paths, Some(TEST_KEY.into())).unwrap().is_some());
}

#[test]
fn team_the_links_of_an_old_start_are_removed() {
    let sb = Sandbox::new("team-links");
    let paths = sb.paths(dist());
    let folder = team::folder(&paths);
    std::fs::create_dir_all(folder.join("agents")).unwrap();
    for f in ["team-link.json", "team-link-manager.json", "team-link-agent-1.json", "agents/agent-1.pid"] {
        std::fs::write(folder.join(f), "x").unwrap();
    }
    std::fs::write(folder.join("other.json"), "x").unwrap();
    plan(&paths, &with_team(&paths, &Choices::default())).unwrap();
    for f in ["team-link.json", "team-link-manager.json", "team-link-agent-1.json", "agents/agent-1.pid"] {
        assert!(!folder.join(f).exists(), "{f}");
    }
    assert!(folder.join("other.json").exists(), "the rest isn't touched");
}

#[test]
fn team_the_choices_are_saved_and_checked() {
    let sb = Sandbox::new("team-choices");
    let paths = sb.paths(dist());
    std::fs::create_dir_all(&paths.data).unwrap();
    assert_eq!(team::read_choices(&paths).unwrap(), Choices { agents: 4, manager: "deepseek".into(), agent: "deepseek".into() });

    let mine = Choices { agents: 2, manager: "qwen".into(), agent: "deepseek".into() };
    team::write_choices(&paths, &mine).unwrap();
    assert_eq!(team::read_choices(&paths).unwrap(), mine);

    // five agents, a model that isn't there, a local model: errors that say what, and the file doesn't change
    for (bad, expected) in [
        (Choices { agents: 5, ..mine.clone() }, tr!("da 0 a 4", "from 0 to 4")),
        (Choices { manager: "xyz".into(), ..mine.clone() }, "xyz".to_string()),
        (Choices { agent: "toq".into(), ..mine.clone() }, tr!("non è un modello cloud", "is not a cloud model")),
    ] {
        let e = format!("{:#}", team::write_choices(&paths, &bad).unwrap_err());
        assert!(e.contains(&expected), "{e}");
        assert_eq!(team::read_choices(&paths).unwrap(), mine);
    }

    // a wrong hand-written file stops the Team's start, naming it
    std::fs::write(paths.data.join("team.json"), r#"{"agents": 9, "manager": "deepseek", "agent": "deepseek"}"#).unwrap();
    let e = format!("{:#}", team::team_inputs(&paths, Some(TEST_KEY.into())).unwrap_err());
    assert!(e.contains("team.json") && e.contains(&tr!("da 0 a 4", "from 0 to 4")), "{e}");
}
